const {chromium}=require('/Users/ahimanikya/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const fs=require('fs'),path=require('path'),assert=require('assert');
const crypto=require('crypto'),cp=require('child_process');const repo=process.cwd(),story=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/collection.json'))).pages.find(p=>p.slug==='tala-pitha'),editorial=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/tala-pitha-editorial.json'))),base=process.argv[2]||'http://127.0.0.1:8833',out=path.resolve(process.argv[3]||__dirname);
const foods=JSON.parse(fs.readFileSync(path.join(repo,'kb/research/food/collection.json'))),photo=foods.assets[story.hero];
(async()=>{fs.mkdirSync(out,{recursive:true});const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});const results=[];
for(const [name,width,height] of [['desktop',1440,900],['phone',390,844]]){const context=await browser.newContext({viewport:{width,height},acceptDownloads:true});const page=await context.newPage();await page.goto(base+'/food/tala-pitha/',{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);const hero=page.locator('.mag-cover img');await hero.evaluate(async image=>{if(!image.complete)await new Promise(r=>image.addEventListener('load',r,{once:true}));await image.decode();});const imageState=await hero.evaluate(i=>({src:i.getAttribute('src'),currentSrc:i.currentSrc,naturalWidth:i.naturalWidth,naturalHeight:i.naturalHeight,alt:i.alt}));assert(imageState.naturalWidth>0);assert.equal(imageState.alt,photo.alt);await page.screenshot({path:path.join(out,name+'-opening.png')});assert.equal(await page.locator('h1').evaluate(h=>{const c=h.cloneNode(true);c.querySelectorAll('[lang=or],.odia').forEach(n=>n.remove());return c.textContent.trim();}),story.title);const rendered=await page.locator('article p[data-source-ids]').evaluateAll(nodes=>nodes.map(node=>{const copy=node.cloneNode(true);copy.querySelectorAll('sup').forEach(n=>n.remove());return copy.textContent.trim();}));assert.deepEqual(rendered,story.sections.flatMap(s=>s.paragraphs.map(p=>p.text)));assert.equal(await page.locator('article sup a').count(),story.sections.flatMap(s=>s.paragraphs).reduce((n,p)=>n+p.source_ids.length,0));let returns=0;
for(const id of await page.locator('article sup a').evaluateAll(a=>a.map(e=>e.id))){const link=page.locator('[id="'+id+'"]');const target=await link.getAttribute('href');await link.focus();await page.keyboard.press('Enter');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>location.hash),target);const back=page.locator('a[href="#'+id+'"]').last();await back.focus();await page.keyboard.press('Enter');await page.waitForTimeout(80);assert.equal(await page.evaluate(()=>location.hash),'#'+id);returns++;}
await page.locator('#story-sources').scrollIntoViewIfNeeded();await page.screenshot({path:path.join(out,name+'-sources.png')});assert.equal(await page.locator('#food-further-reading details').count(),0);for(const link of [...story.related,{href:'/journey/'}])assert(await page.locator('#food-further-reading a[href=\"'+link.href+'\"]').count());const metrics=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));assert(metrics.scrollWidth<=width);const save=page.locator('[data-save-journey="food:tala-pitha"]');await save.click();await page.reload({waitUntil:'networkidle'});assert.match(await save.textContent(),/Saved/);await page.goto(base+'/journey/',{waitUntil:'networkidle'});assert((await page.locator('body').innerText()).includes(story.title));const downloadPromise=page.waitForEvent('download');await page.locator('#illustrated-book').click();const download=await downloadPromise;const file=path.join(out,name+'-reading.html');await download.saveAs(file);const html=fs.readFileSync(file,'utf8');assert(html.includes(photo.creator));assert(html.includes(photo.license_url));assert(/data:image\//.test(html));assert(!/<h4>\s*<\/h4>/.test(html));const parse=await context.newPage();await parse.goto('file://'+file);const portable=await parse.locator('body').innerText();for(const p of story.sections.flatMap(s=>s.paragraphs.map(p=>p.text)))assert(portable.includes(p));for(const s of editorial.sources)for(const link of [{text:s.id==='food-tala-delite2015'?'Delite, Tala poda pitha (2015).':'Oriyarasoi, Talaa Pitha (2016).',href:s.url}]){assert(portable.includes(link.text));assert(html.includes(new URL(link.href).href.replaceAll('&','&amp;')));}
const pendingText=page.waitForEvent('download');await page.locator('#plain-itinerary').click();const textDownload=await pendingText;const textFile=path.join(out,name+'-reading.txt');await textDownload.saveAs(textFile);const textBody=fs.readFileSync(textFile,'utf8');assert(!textBody.includes(': '+story.sections[0].paragraphs[0].text));for(const p of story.sections.flatMap(s=>s.paragraphs))assert.equal(textBody.split(p.text).length-1,1);for(const source of editorial.sources)for(const link of [{text:source.id==='food-tala-delite2015'?'Delite, Tala poda pitha (2015).':'Oriyarasoi, Talaa Pitha (2016).',href:source.url}]){assert(textBody.includes(link.text));assert(textBody.includes(new URL(link.href).href));}results.push({actualTextDownload:textFile,twoParagraphsOnce:true,twoShortSources:true,name,imageState,viewport:{width,height},metrics,keyboardNoteReturns:returns,saveReload:true,actualOfflineDownload:file,allParagraphsAndShortSources:true});await context.close();}
await browser.close();fs.writeFileSync(path.join(out,'browser-review.json'),JSON.stringify({status:'PASS',checked_at:new Date().toISOString(),tested_head:cp.execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),working_tree_basis:'HEAD identifies checkout; actual uncommitted implementation is bound separately by source/product hashes.',article_source_sha256:crypto.createHash('sha256').update(fs.readFileSync(path.join(repo,'kb/research/food/tala-pitha-editorial.json'))).digest('hex'),base,browser:'Actual headless Google Chrome',results,limits:['Not assistive-technology testing or Firefox/WebKit.']},null,2));console.log('PASS desktop/phone, all keyboard returns,save/reload,actual downloads');})().catch(e=>{console.error(e);process.exit(1)});
